async function createValidatorWorkPackages(config2, input) {
  if (config2.validatorMode === "skip") {
    return void 0;
  }
  const intervalSeconds = numberEnv("SWITCHBOARD_DEPLOY_VALIDATOR_WORK_INTERVAL_SECONDS", 300);
  const checkTimeoutMs = numberEnv("SWITCHBOARD_DEPLOY_VALIDATOR_TIMEOUT_MS", 15e3);
  const leaseSeconds = config2.leaseSeconds ?? 3600;
  const bufferSeconds = Math.max(3600, (config2.scheduleBufferMinutes ?? 10) * 60);
  const expiresAt = new Date(Date.now() + (leaseSeconds + bufferSeconds) * 1e3).toISOString();
  const count = validatorTargetCount(config2);
  const relayUrls = await validatorWorkPackageRelayUrls(config2);
  const authHeader = bearerAuthHeader(requiredEnv("PROOF_CONTROL_PLANE_TOKEN"));
  const work = [];
  for (let index = 0; index < count; index += 1) {
    const slot = index + 1;
    const workId = ethers_exports.keccak256(
      ethers_exports.solidityPacked(
        ["bytes32", "string", "string", "uint256"],
        [input.sessionId, input.hostname, input.deploymentId, slot]
      )
    );
    const payload = {
      workId,
      sessionId: input.sessionId,
      hostname: input.hostname,
      deploymentId: input.deploymentId,
      operatorId: config2.operatorId,
      mode: "route_open",
      port: 443,
      intervalSeconds,
      checkTimeoutMs,
      expiresAt,
      source: {
        mode: "switchboard-deploy",
        runId: config2.runId,
        durationMinutes: config2.durationMinutes,
        leaseSeconds: config2.leaseSeconds,
        validatorSlot: slot,
        validatorSlots: count
      }
    };
    let primaryWork;
    for (const relayUrl of relayUrls) {
      const response = await fetch(new URL("/v1/validator-work-packages", relayUrl), {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...authHeader
        },
        body: JSON.stringify(payload)
      });
      const body = await response.text();
      if (!response.ok) {
        throw new Error(`validator work package creation failed on ${relayUrl}: ${response.status} ${body}`);
      }
      primaryWork ??= requiredRecordField(parseRequiredJsonObject(body), "work");
    }
    work.push(primaryWork ?? payload);
  }
  return {
    ok: true,
    relays: relayUrls,
    count,
    work
  };
}
async function validatorWorkPackageRelayUrls(config2) {
  const urls = [config2.relayUrl];
  try {
    const response = await fetch(new URL("/v1/network-manifest", config2.relayUrl), {
      headers: {
        accept: "application/json"
      },
      signal: AbortSignal.timeout(5e3)
    });
    if (response.ok) {
      const body = await response.json();
      for (const relay of body.manifest?.relays ?? []) {
        if (relay.active === false || !relay.apiBaseUrl) {
          continue;
        }
        urls.push(relay.apiBaseUrl);
      }
    }
  } catch (error) {
    console.log(deployStatus("warn", "Validator relay discovery skipped", error instanceof Error ? error.message : String(error)));
  }
  return unique(urls.map((value) => new URL(value).toString()));
}
