        ACURAST_START_DELAY_MS: String(validatorStartDelayMs),
        ACURAST_EXECUTION_MS: String(validatorExecutionMs),
        ACURAST_MAX_ALLOWED_START_DELAY_MS: String(numberEnv("SWITCHBOARD_DEPLOY_VALIDATOR_MAX_ALLOWED_START_DELAY_MS", 12e4)),
